window.AUTH=window.AUTH||{};window.AUTH["05-1448"]={"d":"05-1448","id":"2006/05-1448","n":"Beck v. PACE International Union","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting petitioner","date":"","url":"https://www.justice.gov/osg/media/212901/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/beck-v-pace-intl-union-amicus-merits","n":83}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep551/usrep551096/usrep551096.pdf","tr":true,"items":[{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Boivin v. U.S. Airways, Inc.","cite":"446 F.3d 148","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/446/148/","by":{"0":"21"}},{"t":"case","label":"Brillinger v. General Elec. Co.","cite":"130 F.3d 61","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/130/61/","by":{"0":"24"}},{"t":"case","label":"Chait v. Bernstein","cite":"835 F.2d 1017","y":1988,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/835/1017/","by":{"0":"28"}},{"t":"case","label":"Curtiss-Wright Corp. v. Schoonejongen","cite":"514 U.S. 73","y":1995,"id":"1994/93-1935","sc":1,"op":1,"ar":1,"sum":"Petitioner Curtiss-Wright Corp. amended its employee benefit plan to provide that the postretirement health care coverage it had maintained for many years would cease for retirees upon the termination of business operations in the facility from which they retired. In ruling for respondent retirees in their ensuing suit, the District Court found, among other things, that the new provision constituted an \"amendment\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 15"}},{"t":"case","label":"Flanigan v. General Elec. Co.","cite":"242 F.3d 78","y":2001,"url":"https://www.courtlistener.com/c/F.3d/242/78/","by":{"0":"15"}},{"t":"case","label":"Hawkeye Nat’l Life Ins. Co. v. Avis Indus. Corp.","cite":"122 F.3d 490","y":1997,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/122/490/","by":{"0":"28"}},{"t":"case","label":"King v. National Human Res. Comm., Inc.","cite":"218 F.3d 719","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/218/719/","by":{"0":"15"}},{"t":"case","label":"Hughes Aircraft Co. v. Jacobson","cite":"525 U.S. 432","y":1999,"id":"1998/97-1287","sc":1,"op":4,"sum":"The Court held Hughes did not violate the ERISA by establishing an early retirement program and creating a noncontributory benefit structure for new participants. Justice Thomas, writing for the Court, said the plan amendments \"did not affect the rights of pre-existing plan participants and Hughes did not use the surplus for its own benefit.\".","sumSrc":"Oyez","by":{"0":"2, 11, 13, 18, 19"}},{"t":"case","label":"Lockheed Corp. v. Spink","cite":"517 U.S. 882","y":1996,"id":"1995/95-809","sc":1,"op":1,"ar":1,"sum":"In unanimous and 7-2 decisions, announced by Justice Clarence Thomas, the Court ruled that businesses may condition early retirement benefits on the forfeiture of the right to sue in a job-related claim. The Court also ruled that the government could not retroactively apply retirement income benefit laws.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Malia v. General Elec. Co.","cite":"23 F.3d 828","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/23/828/","op":1,"sum":"Holding that employer’s decision to merge plans “d[id] not invoke the ﬁduciary duty provisions of ERISA”.","sumSrc":"opinion","by":{"0":"13, 15, 24"}},{"t":"case","label":"Mead Corp. v. Tilley","cite":"490 U.S. 714","y":1989,"id":"1988/87-1868","sc":1,"op":2,"sum":"Under the Employee Retirement Income Security Act of 1974 (ERISA), the Pension Benefit Guaranty Corporation (PBGC) guarantees certain nonforfeitable benefits provided by qualified defined benefit pension plans. When an employer voluntarily terminates a single-employer defined benefit plan, all accrued benefits automatically vest, notwithstanding the plan's particular vesting provisions. Plan assets are then …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 13, 19"}},{"t":"case","label":"Nachman Corp. v. PBGC","cite":"446 U.S. 359","y":1980,"id":"1979/78-1557","sc":1,"sum":"The plan's limitation of liability clause does not prevent the vested benefits from being characterized as \"nonforfeitable\" and thus covered by the insurance program. Petitioner's argument that the Title I definition of \"nonforfeitable\" determines which benefits are insured under Title IV, that thus benefits are not insured unless they are \"unconditional\" and \"legally enforceable against the plan,\" that because of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 14"}},{"t":"case","label":"Pegram v. Herdrich","cite":"530 U.S. 211","y":2000,"id":"1999/98-1949","sc":1,"op":1,"ar":1,"sum":"The Court held that mixed treatment and eligibility decisions to delay medical treatment by sending a patient to a HMO owned facility, with adverse consequences, made by a health maintenance organization through its physician, are not fiduciary decisions under ERISA.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Shaw v. Delta Air Lines, Inc.","cite":"463 U.S. 85","y":1983,"id":"1982/81-1578","sc":1,"sum":"New York's Human Rights Law forbids discrimination in employee benefit plans on the basis of pregnancy, and its Disability Benefits Law requires employers to pay sick-leave benefits to employees unable to work because of pregnancy. Section 514(a) of the federal Employee Retirement Income Security Act of 1974 (ERISA) provides, with enumerated exceptions, that ERISA shall supersede \"any and all state laws insofar as …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Sutter v. BASF Corp.","cite":"964 F.2d 556","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/964/556/","by":{"0":"15"}},{"t":"case","label":"Systems Council EM-3 v. AT&T Corp.","cite":"159 F.3d 1376","y":1998,"court":"D.C. Cir","url":"https://www.courtlistener.com/c/F.3d/159/1376/","by":{"0":"16"}},{"t":"case","label":"Varity Corp. v. Howe","cite":"516 U.S. 489","y":1996,"id":"1995/94-1471","sc":1,"sum":"The Court held that, under the specific factual circumstances, Varity and Massey-Ferguson acted in their capacity as an ERISA fiduciary when they significantly and deliberately misled the plan's beneficiaries, thereby violating their fiduciary obligations imposed by ERISA.","sumSrc":"Oyez","by":{"0":"9, 11"}},{"t":"case","label":"Waller v. Blue Cross","cite":"32 F.3d 1337","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/32/1337/","by":{"0":"6"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","subs":["(a)","(b)","(c)"],"stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"1, 23, 1, 23, 14, 28, 2, 2, 2"}},{"t":"usc","label":"29 U.S.C. § 1001a","url":"https://www.law.cornell.edu/uscode/text/29/1001a","subs":["(c)"],"by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 1001b","url":"https://www.law.cornell.edu/uscode/text/29/1001b","subs":["(a)","(c)"],"by":{"0":"2, 2"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(16)(A)","(16)(B)(i)","(16)(B)(ii)","(16)(B)(iii)","(21)(A)(i)","(21)(A)(iii)","(35)","(37)"],"by":{"0":"2, 2, 2, 2, 2, 2, 2, 4"}},{"t":"usc","label":"29 U.S.C. § 1058","url":"https://www.law.cornell.edu/uscode/text/29/1058","stext":{"head":"§1058. Mergers and consolidations of plans or transfers of plan assets","paras":[[0,"A pension plan may not merge or consolidate with, or transfer its assets or liabilities to, any other plan after September 2, 1974, unless each participant in the plan would (if the plan then terminated) receive a benefit immediately after the merger, consolidation, or transfer which is equal to or greater than the benefit he would have been entitled to receive immediately before the merger, consolidation, or transfer (if the plan had then terminated). The preceding sentence shall not apply to any transaction to the extent that participants either before or after the transaction are covered under a multiemployer plan to which subchapter III of this chapter applies."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1058?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§1058. Mergers and consolidations of plans or transfers of plan assets","tname":"Labor","by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 1081","url":"https://www.law.cornell.edu/uscode/text/29/1081","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 1082","url":"https://www.law.cornell.edu/uscode/text/29/1082","by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/29/1102","subs":["(b)(3)"],"by":{"0":"10"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)","(a)(1)(A)","(a)(1)(B)","(a)(1)(D)"],"by":{"0":"14, 14, 14, 14"}},{"t":"usc","label":"29 U.S.C. § 1106","url":"https://www.law.cornell.edu/uscode/text/29/1106","subs":["(a)"],"by":{"0":"14"}},{"t":"usc","label":"29 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/29/1301","subs":["(a)(3)"],"by":{"0":"2, 23, 4"}},{"t":"usc","label":"29 U.S.C. § 1322","url":"https://www.law.cornell.edu/uscode/text/29/1322","stext":{"head":"§1322. Single-employer plan benefits guaranteed","paras":[[0,"(a) Nonforfeitable benefits"],[0,"Subject to the limitations contained in subsection (b), the corporation shall guarantee, in accordance with this section, the payment of all nonforfeitable benefits (other than benefits becoming nonforfeitable solely on account of the termination of a plan) under a single-employer plan which terminates at a time when this subchapter applies to it."],[0,"(b) Exceptions"],[0,"(1) Except to the extent provided in paragraph (7)—"],[1,"(A) no benefits provided by a plan which has been in effect for less than 60 months at the time the plan terminates shall be guaranteed under this section, and"],[1,"(B) any increase in the amount of benefits under a plan resulting from a plan amendment which was made, or became effective, whichever is later, within 60 months before the date on which the plan terminates shall be disregarded."],[0,"(2) For purposes of this subsection, the time a successor plan (within the meaning of section 1321(a) of this title) has been in effect includes the time a previously established plan (within the meaning of section 1321(a) of this title) was in effect. For purposes of determining what benefits are guaranteed under this section in the case of a plan to which section 1321 of this title does not apply on September 3, 1974, the 60-month period referred to in paragraph (1) shall be computed beginning on the first date on which such section does apply to the plan."],[0,"(3) The amount of monthly benefits described in subsection (a) provided by a plan, which are guaranteed under this section with respect to a participant, shall not have an actuarial value which exceeds the actuarial value of a monthly benefit in the form of a life annuity commencing at age 65 equal to the lesser of—"],[1,"(A) his average monthly gross income from his employer during the 5 consecutive calendar year period (or, if less, during the number of calendar years in such period in which he actively participates in the plan) during which his gross income from that employer was greater than during any other such period with that employer determined by dividing 1/12 of the sum of all such gross income by the number of such calendar years in which he had such gross income, or"],[1,"(B) $750 multiplied by a fraction, the numerator of which is the contribution and benefit base (determined under section 230 of the Social Security Act [42 U.S.C. 430]) in effect at the time the plan terminates and the denominator of which is such contribution and benefit base in effect in calendar year 1974."],[0,"The provisions of this paragraph do not apply to non-basic benefits. The maximum guaranteed monthly benefit shall not be reduced solely on account of the age of a participant in the case of a benefit payable by reason of disability that occurred on or before the termination date, if the participant demonstrates to the satisfaction of the corporation that the Social Security Administration has determined that the participant satisfies the definition of disability under title II or XVI of the Social Security Act [42 U.S.C. 401 et seq.; 1381 et seq.], and the regulations thereunder. If a benefit payable by reason of disability is converted to an early or normal retirement benefit for reasons other than a change in the health of the participant, such early or normal retirement benefit shall be treated as a continuation of the benefit payable by reason of disability and this subparagraph 1 shall continue to apply."],[0,"(4)(A) The actuarial value of a benefit, for purposes of this subsection, shall be determined in accordance with regulations prescribed by the corporation."],[0,"(B) For purposes of paragraph (3)—"],[1,"(i) the term \"gross income\" means \"earned income\" within the meaning of section 911(b) of title 26 (determined without regard to any community property laws),"],[1,"(ii) in the case of a participant in a plan under which contributions are made by more than one employer, amounts received as gross income from any employer under that plan shall be aggregated with amounts received from any other employer under that plan during the same period, and"],[1,"(iii) any non-basic benefit shall be disregarded."],[0,"(5)(A) For purposes of this paragraph, the term \"majority owner\" means an individual who, at any time during the 60-month period ending on the date the determination is being made—"],[1,"(i) owns the entire interest in an unincorporated trade or business,"],[1,"(ii) in the case of a partnership, is a partner who owns, directly or indirectly, 50 percent or more of either the capital interest or the profits interest in such partnership, or"],[1,"(iii) in the case of a corporation, owns, directly or indirectly, 50 percent or more in value of either the voting stock of that corporation or all the stock of that corporation."],[0,"For purposes of clause (iii), the constructive ownership rules of section 1563(e) of title 26 (other than paragraph (3)(C) thereof) shall apply, including the application of such rules under section 414(c) of title 26."],[0,"(B) In the case of a participant who is a majority owner, the amount of benefits guaranteed under this section shall equal the product of—"],[1,"(i) a fraction (not to exceed 1) the numerator of which is the number of years from the later of the effective date or the adoption date of the plan to the termination date, and the denominator of which is 10, and"],[1,"(ii) the amount of benefits that would be guaranteed under this section if the participant were not a majority owner."],[0,"(6)(A) No benefits accrued under a plan after the date on which the Secretary of the Treasury issues notice that he has determined that any trust which is a part of a plan does not meet the requirements of section 401(a) of title 26, or that the plan does not meet the requirements of section 404(a)(2) of title 26, are guaranteed under this section unless such determination is erroneous. This subparagraph does not apply if the Secretary subsequently issues a notice that such trust meets the requirements of section 401(a) of title 26 or that the plan meets the requirements of section 404(a)(2) of title 26 and if the Secretary determines that the trust or plan has taken action necessary to meet such requirements during the period between the issuance of the notice referred to in the preceding sentence and the issuance of the notice referred to in this sentence."],[0,"(B) No benefits accrued under a plan after the date on which an amendment of the plan is adopted which causes the Secretary of the Treasury to determine that any trust under the plan has ceased to meet the requirements of section 401(a) of title 26 or that the plan has ceased to meet the requirements of section 404(a)(2) of title 26, are guaranteed under this section unless such determination is erroneous. This subparagraph shall not apply if the amendment is revoked as of the date it was first effective or amended to comply with such requirements."],[0,"(7) Benefits described in paragraph (1) are guaranteed only to the extent of the greater of—"],[1,"(A) 20 percent of the amount which, but for the fact that the plan or amendment has not been in effect for 60 months or more, would be guaranteed under this section, or"],[1,"(B) $20 per month,"],[0,"multiplied by the number of years (but not more than 5) the plan or amendment, as the case may be, has been in effect. In determining how many years a plan or amendment has been in effect for purposes of this paragraph, the first 12 months beginning with the date on which the plan or amendment is made or first becomes effective (whichever is later) constitutes one year, and each consecutive period of 12 months thereafter constitutes an additional year. This paragraph does not apply to benefits payable under a plan unless the corporation finds substantial evidence that the plan was terminated for a reasonable business purpose and not for the purpose of obtaining the payment of benefits by the corporation under this subchapter."],[0,"(8) If an unpredictable contingent event benefit (as defined in section 1056(g)(1) of this title) is payable by reason of the occurrence of any event, this section shall be applied as if a plan amendment had been adopted on the date such event occurred."],[0,"(c) Payment by corporation to participants and beneficiaries of recovery percentage of outstanding amount of benefit liabilities"],[0,"(1) In addition to benefits paid under the preceding provisions of this section with respect to a terminated plan, the corporation shall pay the portion of the amount determined under paragraph (2) which is allocated with respect to each participant under section 1344(a) of this title. Such payment shall be made to such participant or to such participant's beneficiaries (including alternate payees, within the meaning of section 1056(d)(3)(K) of this title)."],[0,"(2) The amount determined under this paragraph is an amount equal to the product derived by multiplying—"],[1,"(A) the outstanding amount of benefit liabilities under the plan (including interest calculated from the termination date), by"],[1,"(B) the applicable recovery ratio."],[0,"(3)(A) In general.—Except as provided in subparagraph (C), the term \"recovery ratio\" means the ratio which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1322?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1322. Single-employer plan benefits guaranteed","tname":"Labor","by":{"0":"29"}},{"t":"usc","label":"29 U.S.C. § 1322a","url":"https://www.law.cornell.edu/uscode/text/29/1322a","stext":{"head":"§1322a. Multiemployer plan benefits guaranteed","paras":[[0,"(a) Benefits of covered plans subject to guarantee"],[0,"The corporation shall guarantee, in accordance with this section, the payment of all nonforfeitable benefits (other than benefits becoming nonforfeitable solely on account of the termination of a plan) under a multiemployer plan—"],[1,"(1) to which this subchapter applies, and"],[1,"(2) which is insolvent under section 1426(b) or 1441(d)(2) of this title."],[0,"(b) Benefits or benefit increases not eligible for guarantee"],[0,"(1)(A) For purposes of this section, a benefit or benefit increase which has been in effect under a plan for less than 60 months is not eligible for the corporation's guarantee. For purposes of this paragraph, any month of any plan year during which the plan was insolvent or terminated (within the meaning of section 1341a(a)(2) of this title) shall not be taken into account."],[0,"(B) For purposes of this section, a benefit or benefit increase which has been in effect under a plan for less than 60 months before the first day of the plan year for which an amendment reducing the benefit or the benefit increase is taken into account under section 1425(a)(2) 1 of this title in determining the minimum contribution requirement for the plan year under section 1423(b) 1 of this title is not eligible for the corporation's guarantee."],[0,"(2) For purposes of this section—"],[1,"(A) the date on which a benefit or a benefit increase under a plan is first in effect is the later of—"],[2,"(i) the date on which the documents establishing or increasing the benefit were executed, or"],[2,"(ii) the effective date of the benefit or benefit increase;"],[1,"(B) the period of time for which a benefit or a benefit increase has been in effect under a successor plan includes the period of time for which the benefit or benefit increase was in effect under a previously established plan; and"],[1,"(C) in the case of a plan to which section 1321 of this title did not apply on September 3, 1974, the time periods referred to in this section are computed beginning on the date on which section 1321 of this title first applies to the plan."],[0,"(c) Determinations respecting amount of guarantee"],[0,"(1) Except as provided in subsection (g), the monthly benefit of a participant or a beneficiary which is guaranteed under this section by the corporation with respect to a plan is the product of—"],[1,"(A) 100 percent of the accrual rate up to $11, plus 75 percent of the lesser of—"],[2,"(i) $33, or"],[2,"(ii) the accrual rate, if any, in excess of $11, and"],[1,"(B) the number of the participant's years of credited service."],[0,"(2) For purposes of this section, the accrual rate is—"],[1,"(A) the monthly benefit of the participant or beneficiary which is described in subsection (a) and which is eligible for the corporation's guarantee under subsection (b), except that such benefit shall be—"],[2,"(i) no greater than the monthly benefit which would be payable under the plan at normal retirement age in the form of a single life annuity, and"],[2,"(ii) determined without regard to any reduction under section 411(a)(3)(E) of title 26; divided by"],[1,"(B) the participant's years of credited service."],[0,"(3) For purposes of this subsection—"],[1,"(A) a year of credited service is a year in which the participant completed—"],[2,"(i) a full year of participation in the plan, or"],[2,"(ii) any period of service before participation which is credited for purposes of benefit accrual as the equivalent of a full year of participation;"],[1,"(B) any year for which the participant is credited for purposes of benefit accrual with a fraction of the equivalent of a full year of participation shall be counted as such a fraction of a year of credited service; and"],[1,"(C) years of credited service shall be determined by including service which may otherwise be disregarded by the plan under section 411(a)(3)(E) of title 26."],[0,"(4) For purposes of subsection (a), in the case of a qualified preretirement survivor annuity (as defined in section 1055(e)(1) of this title) payable to the surviving spouse of a participant under a multiemployer plan which becomes insolvent under section 1426(b) of this title or 1441(d)(2) of this title or is terminated, such annuity shall not be treated as forfeitable solely because the participant has not died as of the date on which the plan became so insolvent or the termination date."],[0,"(d) Amount of guarantee of reduced benefit"],[0,"In the case of a benefit which has been reduced under section 411(a)(3)(E) of title 26, the corporation shall guarantee the lesser of—"],[1,"(1) the reduced benefit, or"],[1,"(2) the amount determined under subsection (c)."],[0,"(e) Ineligibility of benefits for guarantee"],[0,"The corporation shall not guarantee benefits under a multiemployer plan which, under section 1322(b)(6) of this title, would not be guaranteed under a single-employer plan."],[0,"(f) Study, report, etc., respecting premium increase in existing basic-benefit guarantee levels; Congressional procedures applicable for revision of schedules"],[0,"(1) No later than 5 years after September 26, 1980, and at least every fifth year thereafter, the corporation shall—"],[1,"(A) conduct a study to determine—"],[2,"(i) the premiums needed to maintain the basic-benefit guarantee levels for multiemployer plans described in subsection (c), and"],[2,"(ii) whether the basic-benefit guarantee levels for multiemployer plans may be increased without increasing the basic-benefit premiums for multiemployer plans under this subchapter; and"],[1,"(B) report such determinations to the Committee on Ways and Means and the Committee on Education and Labor of the House of Representatives and to the Committee on Finance and the Committee on Labor and Human Resources of the Senate."],[0,"(2)(A) If the last report described in paragraph (1) indicates that a premium increase is necessary to support the existing basic-benefit guarantee levels for multiemployer plans, the corporation shall transmit to the Committee on Ways and Means and the Committee on Education and Labor of the House of Representatives and to the Committee on Finance and the Committee on Labor and Human Resources of the Senate by March 31 of any calendar year in which congressional action under this subsection is requested—"],[1,"(i) a revised schedule of basic-benefit guarantees for multiemployer plans which would be necessary in the absence of an increase in premiums approved in accordance with section 1306(b) of this title,"],[1,"(ii) a revised schedule of basic-benefit premiums for multiemployer plans which is necessary to support the existing basic-benefit guarantees for such plans, and"],[1,"(iii) a revised schedule of basic-benefit guarantees for multiemployer plans for which the schedule of premiums necessary is higher than the existing premium schedule for such plans but lower than the revised schedule of premiums for such plans specified in clause (ii), together with such schedule of premiums."],[0,"(B) The revised schedule of increased premiums referred to in subparagraph (A)(ii) or (A)(iii) shall go into effect as approved by the enactment of a joint resolution."],[0,"(C) If an increase in premiums is not so enacted, the revised guarantee schedule described in subparagraph (A)(i) shall go into effect on the first day of the second calendar year following the year in which such revised guarantee schedule was submitted to the Congress."],[0,"(3)(A) If the last report described in paragraph (1) indicates that basic-benefit guarantees for multiemployer plans can be increased without increasing the basic-benefit premiums for multiemployer plans under this subchapter, the corporation shall submit to the Committee on Ways and Means and the Committee on Education and Labor of the House of Representatives and to the Committee on Finance and the Committee on Labor and Human Resources of the Senate by March 31 of the calendar year in which congressional action under this paragraph is requested—"],[1,"(i) a revised schedule of increases in the basic-benefit guarantees which can be supported by the existing schedule of basic-benefit premiums for multiemployer plans, and"],[1,"(ii) a revised schedule of basic-benefit premiums sufficient to support the existing basic-benefit guarantees."],[0,"(B) The revised schedules referred to in subparagraph (A)(i) or subparagraph (A)(ii) shall go into effect as approved by the enactment of a joint resolution."],[0,"(4)(A) The succeeding subparagraphs of this paragraph are enacted by the Congress as an exercise of the rulemaking power of the Senate and the House of Representatives, respectively, and as such they shall be deemed a part of the rules of each House, respectively, but applicable only with respect to the procedure to be followed in that House in the case of joint resolutions (as defined in subparagraph (B)). Such subparagraphs shall supersede other rules only to the extent that they are inconsistent therewith. They are enacted with full recognition of the constitutional right of either House to change the rules (so far as relating to the procedure of that House) at any time, in the same manner, and to the same extent as in the case of any rule of that House."],[0,"(B) For purposes of this subsection, \"joint resolution\" means only a joint resolution, the matter after the resolving clause of which is as follows: \"The proposed schedule described in transmitted to the Congress by the Pension Benefit Guaranty Corporation on is hereby approved.\", the first blank space therein being filled with \"section 4022A(f)(2)(A)(ii) of the Employee Retirement Income Security Act of 1974\", \"section 4022A(f)(2)(A)(iii) of the Employee Retirement Income Security Act of 1974\", \"section 4022A(f)(3)(A)(i) of the Employee Retirement Income Security Act of 1974\", or \"section 4022A(f)(3)(A)(ii) of the Employee Retirement Income Security Act of 1974\" (whichever is applicable), and the second blank space therein being filled with the date on which the corporation's message proposing the revision was submitted."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1322a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1322a. Multiemployer plan benefits guaranteed","tname":"Labor","by":{"0":"29"}},{"t":"usc","label":"29 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/29/1341","subs":["(a)(1)","(a)(2)","(b)","(b)(1)(A)","(b)(1)(B)","(b)(2)","(b)(2)(C)","(b)(2)(D)","(b)(3)","(b)(3)(A)","(b)(3)(A)(i)","(b)(3)(A)(ii)"],"stext":{"head":"§1341. Termination of single-employer plans","paras":[[0,"(a) General rules governing single-employer plan terminations"],[0,"(1) Exclusive means of plan termination"],[1,"Except in the case of a termination for which proceedings are otherwise instituted by the corporation as provided in section 1342 of this title, a single-employer plan may be terminated only in a standard termination under subsection (b) or a distress termination under subsection (c)."],[0,"(2) 60-day notice of intent to terminate"],[1,"Not less than 60 days before the proposed termination date of a standard termination under subsection (b) or a distress termination under subsection (c), the plan administrator shall provide to each affected party (other than the corporation in the case of a standard termination) a written notice of intent to terminate stating that such termination is intended and the proposed termination date. The written notice shall include any related additional information required in regulations of the corporation."],[0,"(3) Adherence to collective bargaining agreements"],[1,"The corporation shall not proceed with a termination of a plan under this section if the termination would violate the terms and conditions of an existing collective bargaining agreement. Nothing in the preceding sentence shall be construed as limiting the authority of the corporation to institute proceedings to involuntarily terminate a plan under section 1342 of this title."],[0,"(b) Standard termination of single-employer plans"],[0,"(1) General requirements"],[1,"A single-employer plan may terminate under a standard termination only if—"],[2,"(A) the plan administrator provides the 60-day advance notice of intent to terminate to affected parties required under subsection (a)(2),"],[2,"(B) the requirements of subparagraphs (A) and (B) of paragraph (2) are met,"],[2,"(C) the corporation does not issue a notice of noncompliance under subparagraph (C) of paragraph (2), and"],[2,"(D) when the final distribution of assets occurs, the plan is sufficient for benefit liabilities (determined as of the termination date)."],[0,"(2) Termination procedure"],[0,"(A) Notice to the corporation"],[2,"As soon as practicable after the date on which the notice of intent to terminate is provided pursuant to subsection (a)(2), the plan administrator shall send a notice to the corporation setting forth—"],[3,"(i) certification by an enrolled actuary—"],[4,"(I) of the projected amount of the assets of the plan (as of a proposed date of final distribution of assets),"],[4,"(II) of the actuarial present value (as of such date) of the benefit liabilities (determined as of the proposed termination date) under the plan, and"],[4,"(III) that the plan is projected to be sufficient (as of such proposed date of final distribution) for such benefit liabilities,"],[3,"(ii) such information as the corporation may prescribe in regulations as necessary to enable the corporation to make determinations under subparagraph (C), and"],[3,"(iii) certification by the plan administrator that—"],[4,"(I) the information on which the enrolled actuary based the certification under clause (i) is accurate and complete, and"],[4,"(II) the information provided to the corporation under clause (ii) is accurate and complete."],[2,"Clause (i) and clause (iii)(I) shall not apply to a plan described in section 412(i) 1 of title 26."],[0,"(B) Notice to participants and beneficiaries of benefit commitments 2"],[2,"No later than the date on which a notice is sent by the plan administrator under subparagraph (A), the plan administrator shall send a notice to each person who is a participant or beneficiary under the plan—"],[3,"(i) specifying the amount of the benefit liabilities (if any) attributable to such person as of the proposed termination date and the benefit form on the basis of which such amount is determined, and"],[3,"(ii) including the following information used in determining such benefit liabilities:"],[4,"(I) the length of service,"],[4,"(II) the age of the participant or beneficiary,"],[4,"(III) wages,"],[4,"(IV) the assumptions, including the interest rate, and"],[4,"(V) such other information as the corporation may require."],[2,"Such notice shall be written in such manner as is likely to be understood by the participant or beneficiary and as may be prescribed in regulations of the corporation."],[0,"(C) Notice from the corporation of noncompliance"],[0,"(i) In general"],[3,"Within 60 days after receipt of the notice under subparagraph (A), the corporation shall issue a notice of noncompliance to the plan administrator if—"],[4,"(I) it determines, based on the notice sent under paragraph (2)(A) of subsection (b), that there is reason to believe that the plan is not sufficient for benefit liabilities,"],[4,"(II) it otherwise determines, on the basis of information provided by affected parties or otherwise obtained by the corporation, that there is reason to believe that the plan is not sufficient for benefit liabilities, or"],[4,"(III) it determines that any other requirement of subparagraph (A) or (B) of this paragraph or of subsection (a)(2) has not been met, unless it further determines that the issuance of such notice would be inconsistent with the interests of participants and beneficiaries."],[0,"(ii) Extension"],[3,"The corporation and the plan administrator may agree to extend the 60-day period referred to in clause (i) by a written agreement signed by the corporation and the plan administrator before the expiration of the 60-day period. The 60-day period shall be extended as provided in the agreement and may be further extended by subsequent written agreements signed by the corporation and the plan administrator made before the expiration of a previously agreed upon extension of the 60-day period. Any extension may be made upon such terms and conditions (including the payment of benefits) as are agreed upon by the corporation and the plan administrator."],[0,"(D) Final distribution of assets in absence of notice of noncompliance"],[2,"The plan administrator shall commence the final distribution of assets pursuant to the standard termination of the plan as soon as practicable after the expiration of the 60-day (or extended) period referred to in subparagraph (C), but such final distribution may occur only if—"],[3,"(i) the plan administrator has not received during such period a notice of noncompliance from the corporation under subparagraph (C), and"],[3,"(ii) when such final distribution occurs, the plan is sufficient for benefit liabilities (determined as of the termination date)."],[0,"(3) Methods of final distribution of assets"],[0,"(A) In general"],[2,"In connection with any final distribution of assets pursuant to the standard termination of the plan under this subsection, the plan administrator shall distribute the assets in accordance with section 1344 of this title. In distributing such assets, the plan administrator shall—"],[3,"(i) purchase irrevocable commitments from an insurer to provide all benefit liabilities under the plan, or"],[3,"(ii) in accordance with the provisions of the plan and any applicable regulations, otherwise fully provide all benefit liabilities under the plan. A transfer of assets to the corporation in accordance with section 1350 of this title on behalf of a missing participant shall satisfy this subparagraph with respect to such participant."],[0,"(B) Certification to the corporation of final distribution of assets"],[2,"Within 30 days after the final distribution of assets is completed pursuant to the standard termination of the plan under this subsection, the plan administrator shall send a notice to the corporation certifying that the assets of the plan have been distributed in accordance with the provisions of subparagraph (A) so as to pay all benefit liabilities under the plan."],[0,"(4) Continuing authority"],[1,"Nothing in this section shall be construed to preclude the continued exercise by the corporation, after the termination date of a plan terminated in a standard termination under this subsection, of its authority under section 1303 of this title with respect to matters relating to the termination. A certification under paragraph (3)(B) shall not affect the corporation's obligations under section 1322 of this title."],[0,"(5) Special rule for certain plans where cessation or change in membership of a controlled group"],[0,"(A) In general"],[2,"Except as provided in subparagraphs (B) and (D), if—"],[3,"(i) there is 3 transaction or series of transactions which result in a person ceasing to be a member of a controlled group, and"],[3,"(ii) such person immediately before the transaction or series of transactions maintained a single-employer plan which is a defined benefit plan which is fully funded,"],[2,"then the interest rate used in determining whether the plan is sufficient for benefit liabilities or to otherwise assess plan liabilities for purposes of this subsection or section 1342(a)(4) of this title shall be not less than the interest rate used in determining whether the plan is fully funded."],[0,"(B) Limitations"],[2,"Subparagraph (A) shall not apply to any transaction or series of transactions unless—"],[3,"(i) any employer maintaining the plan immediately before or after such transaction or series of transactions—"],[4,"(I) has an outstanding senior unsecured debt instrument which is rated investment grade by each of the nationally recognized statistical rating organizations for corporate bonds that has issued a credit rating for such instrument, or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1341?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":5,"head":"§1341. Termination of single-employer plans","tname":"Labor","by":{"0":"23, 23, 23, 23, 23, 23, 23, 23, 23, 23, 23, 23, 23"}},{"t":"usc","label":"29 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/29/1343","subs":["(a)","(c)(8)"],"by":{"0":"23, 23"}},{"t":"usc","label":"29 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/29/1344","subs":["(a)","(d)(1)","(d)(3)"],"stext":{"head":"§1344. Allocation of assets","paras":[[0,"(a) Order of priority of participants and beneficiaries"],[0,"In the case of the termination of a single-employer plan, the plan administrator shall allocate the assets of the plan (available to provide benefits) among the participants and beneficiaries of the plan in the following order:"],[1,"(1) First, to that portion of each individual's accrued benefit which is derived from the participant's contributions to the plan which were not mandatory contributions."],[1,"(2) Second, to that portion of each individual's accrued benefit which is derived from the participant's mandatory contributions."],[1,"(3) Third, in the case of benefits payable as an annuity—"],[2,"(A) in the case of the benefit of a participant or beneficiary which was in pay status as of the beginning of the 3-year period ending on the termination date of the plan, to each such benefit, based on the provisions of the plan (as in effect during the 5-year period ending on such date) under which such benefit would be the least,"],[2,"(B) in the case of a participant's or beneficiary's benefit (other than a benefit described in subparagraph (A)) which would have been in pay status as of the beginning of such 3-year period if the participant had retired prior to the beginning of the 3-year period and if his benefits had commenced (in the normal form of annuity under the plan) as of the beginning of such period, to each such benefit based on the provisions of the plan (as in effect during the 5-year period ending on such date) under which such benefit would be the least."],[1,"For purposes of subparagraph (A), the lowest benefit in pay status during a 3-year period shall be considered the benefit in pay status for such period."],[1,"(4) Fourth—"],[2,"(A) to all other benefits (if any) of individuals under the plan guaranteed under this subchapter (determined without regard to section 1322b(a) of this title), and"],[2,"(B) to the additional benefits (if any) which would be determined under subparagraph (A) if section 1322(b)(5)(B) of this title did not apply."],[1,"For purposes of this paragraph, section 1321 of this title shall be applied without regard to subsection (c) thereof."],[1,"(5) Fifth, to all other nonforfeitable benefits under the plan."],[1,"(6) Sixth, to all other benefits under the plan."],[0,"(b) Adjustment of allocations; reallocations; mandatory contributions; establishment of subclasses and categories"],[0,"For purposes of subsection (a)—"],[1,"(1) The amount allocated under any paragraph of subsection (a) with respect to any benefit shall be properly adjusted for any allocation of assets with respect to that benefit under a prior paragraph of subsection (a)."],[1,"(2) If the assets available for allocation under any paragraph of subsection (a) (other than paragraphs (4), (5), and (6)) are insufficient to satisfy in full the benefits of all individuals which are described in that paragraph, the assets shall be allocated pro rata among such individuals on the basis of the present value (as of the termination date) of their respective benefits described in that paragraph."],[1,"(3) If assets available for allocation under paragraph (4) of subsection (a) are insufficient to satisfy in full the benefits of all individuals who are described in that paragraph, the assets shall be allocated first to benefits described in subparagraph (A) of that paragraph. Any remaining assets shall then be allocated to benefits described in subparagraph (B) of that paragraph. If assets allocated to such subparagraph (B) are insufficient to satisfy in full the benefits described in that subparagraph, the assets shall be allocated pro rata among individuals on the basis of the present value (as of the termination date) of their respective benefits described in that subparagraph."],[1,"(4) This paragraph applies if the assets available for allocation under paragraph (5) of subsection (a) are not sufficient to satisfy in full the benefits of individuals described in that paragraph."],[2,"(A) If this paragraph applies, except as provided in subparagraph (B), the assets shall be allocated to the benefits of individuals described in such paragraph (5) on the basis of the benefits of individuals which would have been described in such paragraph (5) under the plan as in effect at the beginning of the 5-year period ending on the date of plan termination."],[2,"(B) If the assets available for allocation under subparagraph (A) are sufficient to satisfy in full the benefits described in such subparagraph (without regard to this subparagraph), then for purposes of subparagraph (A), benefits of individuals described in such subparagraph shall be determined on the basis of the plan as amended by the most recent plan amendment effective during such 5-year period under which the assets available for allocation are sufficient to satisfy in full the benefits of individuals described in subparagraph (A) and any assets remaining to be allocated under such subparagraph shall be allocated under subparagraph (A) on the basis of the plan as amended by the next succeeding plan amendment effective during such period."],[1,"(5) If the Secretary of the Treasury determines that the allocation made pursuant to this section (without regard to this paragraph) results in discrimination prohibited by section 401(a)(4) of title 26 then, if required to prevent the disqualification of the plan (or any trust under the plan) under section 401(a) or 403(a) of title 26, the assets allocated under subsections (a)(4)(B), (a)(5), and (a)(6) shall be reallocated to the extent necessary to avoid such discrimination."],[1,"(6) The term \"mandatory contributions\" means amounts contributed to the plan by a participant which are required as a condition of employment, as a condition of participation in such plan, or as a condition of obtaining benefits under the plan attributable to employer contributions. For this purpose, the total amount of mandatory contributions of a participant is the amount of such contributions reduced (but not below zero) by the sum of the amounts paid or distributed to him under the plan before its termination."],[1,"(7) A plan may establish subclasses and categories within the classes described in paragraphs (1) through (6) of subsection (a) in accordance with regulations prescribed by the corporation."],[0,"(c) Increase or decrease in value of assets"],[0,"Any increase or decrease in the value of the assets of a single-employer plan occurring during the period beginning on the later of (1) the date a trustee is appointed under section 1342(b) of this title or (2) the date on which the plan is terminated is to be allocated between the plan and the corporation in the manner determined by the court (in the case of a court-appointed trustee) or as agreed upon by the corporation and the plan administrator in any other case. Any increase or decrease in the value of the assets of a single-employer plan occurring after the date on which the plan is terminated shall be credited to, or suffered by, the corporation."],[0,"(d) Distribution of residual assets; restrictions on reversions pursuant to recently amended plans; assets attributable to employee contributions; calculation of remaining assets"],[0,"(1) Subject to paragraph (3), any residual assets of a single-employer plan may be distributed to the employer if—"],[1,"(A) all liabilities of the plan to participants and their beneficiaries have been satisfied,"],[1,"(B) the distribution does not contravene any provision of law, and"],[1,"(C) the plan provides for such a distribution in these circumstances."],[0,"(2)(A) In determining the extent to which a plan provides for the distribution of plan assets to the employer for purposes of paragraph (1)(C), any such provision, and any amendment increasing the amount which may be distributed to the employer, shall not be treated as effective before the end of the fifth calendar year following the date of the adoption of such provision or amendment."],[0,"(B) A distribution to the employer from a plan shall not be treated as failing to satisfy the requirements of this paragraph if the plan has been in effect for fewer than 5 years and the plan has provided for such a distribution since the effective date of the plan."],[0,"(C) Except as otherwise provided in regulations of the Secretary of the Treasury, in any case in which a transaction described in section 1058 of this title occurs, subparagraph (A) shall continue to apply separately with respect to the amount of any assets transferred in such transaction."],[0,"(D) For purposes of this subsection, the term \"employer\" includes any member of the controlled group of which the employer is a member. For purposes of the preceding sentence, the term \"controlled group\" means any group treated as a single employer under subsection (b), (c), (m) or (o) of section 414 of title 26."],[0,"(3)(A) Before any distribution from a plan pursuant to paragraph (1), if any assets of the plan attributable to employee contributions remain after satisfaction of all liabilities described in subsection (a), such remaining assets shall be equitably distributed to the participants who made such contributions or their beneficiaries (including alternate payees, within the meaning of section 1056(d)(3)(K) of this title)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1344?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1344. Allocation of assets","tname":"Labor","by":{"0":"23, 23, 23, 23"}},{"t":"usc","label":"29 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/29/1350","subs":["(a)(1)","(a)(2)","(b)(1)"],"by":{"0":"23, 23, 23"}},{"t":"usc","label":"29 U.S.C. § 1411","url":"https://www.law.cornell.edu/uscode/text/29/1411","subs":["(a)","(b)","(b)(2)"],"stext":{"head":"§1411. Mergers and transfers between multiemployer plans","paras":[[0,"(a) Authority of plan sponsor"],[0,"Unless otherwise provided in regulations prescribed by the corporation, a plan sponsor may not cause a multiemployer plan to merge with one or more multiemployer plans, or engage in a transfer of assets and liabilities to or from another multiemployer plan, unless such merger or transfer satisfies the requirements of subsection (b)."],[0,"(b) Criteria"],[0,"A merger or transfer satisfies the requirements of this section if—"],[1,"(1) in accordance with regulations of the corporation, the plan sponsor of a multiemployer plan notifies the corporation of a merger with or transfer of plan assets or liabilities to another multiemployer plan at least 120 days before the effective date of the merger or transfer;"],[1,"(2) no participant's or beneficiary's accrued benefit will be lower immediately after the effective date of the merger or transfer than the benefit immediately before that date;"],[1,"(3) the benefits of participants and beneficiaries are not reasonably expected to be subject to suspension under section 1426 of this title; and"],[1,"(4) an actuarial valuation of the assets and liabilities of each of the affected plans has been performed during the plan year preceding the effective date of the merger or transfer, based upon the most recent data available as of the day before the start of that plan year, or other valuation of such assets and liabilities performed under such standards and procedures as the corporation may prescribe by regulation."],[0,"(c) Actions not deemed violation of section 1106(a) or (b)(2) of this title"],[0,"The merger of multiemployer plans or the transfer of assets or liabilities between multiemployer plans, shall be deemed not to constitute a violation of the provisions of section 1106(a) of this title or section 1106(b)(2) of this title if the corporation determines that the merger or transfer otherwise satisfies the requirements of this section."],[0,"(d) Nature of plan to which liabilities are transferred"],[0,"A plan to which liabilities are transferred under this section is a successor plan for purposes of section 1322a(b)(2)(B) of this title."],[0,"(e) Facilitated mergers"],[0,"(1) In general"],[1,"When requested to do so by the plan sponsors, the corporation may take such actions as it deems appropriate to promote and facilitate the merger of two or more multiemployer plans if it determines, after consultation with the Participant and Plan Sponsor Advocate selected under section 1304 of this title, that the transaction is in the interests of the participants and beneficiaries of at least one of the plans and is not reasonably expected to be adverse to the overall interests of the participants and beneficiaries of any of the plans. Such facilitation may include training, technical assistance, mediation, communication with stakeholders, and support with related requests to other government agencies."],[0,"(2) Financial assistance"],[1,"In order to facilitate a merger which it determines is necessary to enable one or more of the plans involved to avoid or postpone insolvency, the corporation may provide financial assistance (within the meaning of section 1431 of this title) to the merged plan if—"],[2,"(A) one or more of the multiemployer plans participating in the merger is in critical and declining status (as defined in section 1085(b)(4) of this title);"],[2,"(B) the corporation reasonably expects that—"],[3,"(i) such financial assistance will reduce the corporation's expected long-term loss with respect to the plans involved; and"],[3,"(ii) such financial assistance is necessary for the merged plan to become or remain solvent;"],[2,"(C) the corporation certifies that its ability to meet existing financial assistance obligations to other plans will not be impaired by such financial assistance; and"],[2,"(D) such financial assistance is paid exclusively from the fund for basic benefits guaranteed for multiemployer plans."],[1,"Not later than 14 days after the provision of such financial assistance, the corporation shall provide notice of such financial assistance to the Committee on Education and the Workforce of the House of Representatives, the Committee on Ways and Means of the House of Representatives, the Committee on Finance of the Senate, and the Committee on Health, Education, Labor, and Pensions of the Senate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1411?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1411. Mergers and transfers between multiemployer plans","tname":"Labor","by":{"0":"23, 23, 23, 23"}},{"t":"usc","label":"29 U.S.C. § 1412","url":"https://www.law.cornell.edu/uscode/text/29/1412","subs":["(b)"],"stext":{"head":"§1412. Transfers between a multiemployer plan and a single-employer plan","paras":[[0,"(a) General authority"],[0,"A transfer of assets or liabilities between, or a merger of, a multiemployer plan and a single-employer plan shall satisfy the requirements of this section."],[0,"(b) Accrued benefit of participant or beneficiary not lower immediately after effective date of transfer or merger"],[0,"No accrued benefit of a participant or beneficiary may be lower immediately after the effective date of a transfer or merger described in subsection (a) than the benefit immediately before that date."],[0,"(c) Liability of multiemployer plan to corporation where single-employer plan terminates within 60 months after effective date of transfer; amount of liability, exemption, etc."],[0,"(1) Except as provided in paragraphs (2) and (3), a multiemployer plan which transfers liabilities to a single-employer plan shall be liable to the corporation if the single-employer plan terminates within 60 months after the effective date of the transfer. The amount of liability shall be the lesser of—"],[1,"(A) the amount of the plan asset insufficiency of the terminated single-employer plan, less 30 percent of the net worth of the employer who maintained the single-employer plan, determined in accordance with section 1362 or 1364 of this title, or"],[1,"(B) the value, on the effective date of the transfer, of the unfunded benefits transferred to the single-employer plan which are guaranteed under section 1322 of this title."],[0,"(2) A multiemployer plan shall be liable to the corporation as provided in paragraph (1) unless, within 180 days after the corporation receives an application (together with such information as the corporation may reasonably require for purposes of such application) from the multiemployer plan sponsor for a determination under this paragraph—"],[1,"(A) the corporation determines that the interests of the plan participants and beneficiaries and of the corporation are adequately protected, or"],[1,"(B) fails to make any determination regarding the adequacy with which such interests are protected with respect to such transfer of liabilities."],[0,"If, after the receipt of such application, the corporation requests from the plan sponsor additional information necessary for the determination, the running of the 180-day period shall be suspended from the date of such request until the receipt by the corporation of the additional information requested. The corporation may by regulation prescribe procedures and standards for the issuance of determinations under this paragraph. This paragraph shall not apply to any application submitted less than 180 days after September 26, 1980."],[0,"(3) A multiemployer plan shall not be liable to the corporation as provided in paragraph (1) in the case of a transfer from the multiemployer plan to a single-employer plan of liabilities which accrued under a single-employer plan which merged with the multiemployer plan, if, the value of liabilities transferred to the single-employer plan does not exceed the value of the liabilities for benefits which accrued before the merger, and the value of the assets transferred to the single-employer plan is substantially equal to the value of the assets which would have been in the single-employer plan if the employer had maintained and funded it as a separate plan under which no benefits accrued after the date of the merger."],[0,"(4) The corporation may make equitable arrangements with multiemployer plans which are liable under this subsection for satisfaction of their liability."],[0,"(d) Guarantee of benefits under single-employer plan"],[0,"Benefits under a single-employer plan to which liabilities are transferred in accordance with this section are guaranteed under section 1322 of this title to the extent provided in that section as of the effective date of the transfer and the plan is a successor plan."],[0,"(e) Transfer of liabilities by multiemployer plan to single-employer plan"],[0,"(1) Except as provided in paragraph (2), a multiemployer plan may not transfer liabilities to a single-employer plan unless the plan sponsor of the plan to which the liabilities would be transferred agrees to the transfer."],[0,"(2) In the case of a transfer described in subsection (c)(3), paragraph (1) of this subsection is satisfied by the advance agreement to the transfer by the employer who will be obligated to contribute to the single-employer plan."],[0,"(f) Additional requirements by corporation for protection of interests of plan participants, beneficiaries and corporation; approval by corporation of transfer of assets or liabilities to single-employer plan from plan in reorganization; covered transfers in connection with termination"],[0,"(1) The corporation may prescribe by regulation such additional requirements with respect to the transfer of assets or liabilities as may be necessary to protect the interests of plan participants and beneficiaries and the corporation."],[0,"(2) Except as otherwise determined by the corporation, a transfer of assets or liabilities to a single-employer plan from a plan in reorganization under section 1421 1 of this title is not effective unless the corporation approves such transfer."],[0,"(3) No transfer to which this section applies, in connection with a termination described in section 1341a(a)(2) of this title shall be effective unless the transfer meets such requirements as may be established by the corporation to prevent an increase in the risk of loss to the corporation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1412?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§1412. Transfers between a multiemployer plan and a single-employer plan","tname":"Labor","by":{"0":"23, 23"}},{"t":"law","label":"Pub. L. No. 109-280","url":"https://www.govinfo.gov/link/plaw/109/public/280","by":{"0":"29"}},{"t":"law","label":"Pub. L. No. 99-272","url":"https://www.govinfo.gov/link/statute/100/244","by":{"0":"23"}},{"t":"usc","label":"26 U.S.C. § 414","url":"https://www.law.cornell.edu/uscode/text/26/414","subs":["(l)"],"by":{"0":"23"}},{"t":"usc","label":"26 U.S.C. § 4975","url":"https://www.law.cornell.edu/uscode/text/26/4975","by":{"0":"14"}},{"t":"usc","label":"28 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/28/402","subs":["(c)"],"by":{"0":"12"}},{"t":"reg","label":"60 Fed. Reg. 12,328","url":"https://www.govinfo.gov/link/fr/60/12328","by":{"0":"17"}}]};